SELECT status, MONTH(shipped_date) AS shipped_month, SUM(CASE WHEN carrier = 'Flash' THEN 1 ELSE 0 END) AS flash_count, ROUND((100 * SUM(CASE WHEN status = 'RETURNED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_returned, COUNT(DISTINCT cost) AS unique_carriers FROM shipments WHERE carrier = 'Kerry' AND status = 'RETURNED' AND carrier IN ('FedEx', 'Flash', 'UPS') GROUP BY status, MONTH(shipped_date) HAVING ROUND((100 * SUM(CASE WHEN status = 'RETURNED' THEN 1 ELSE 0 END)) / COUNT(*), 1) >= 51 ORDER BY flash_count DESC, pct_returned DESC
